<script setup lang="ts">import {onMounted,ref,watch} from 'vue';import {useRoute,useRouter,RouterLink} from 'vue-router';import {api,idr} from '../api';import {useSession} from '../stores';const session=useSession(),route=useRoute(),router=useRouter(),orders=ref<any[]>([]),addresses=ref<any[]>([]),error=ref('');async function load(){if(!session.user)return router.push('/login');try{[orders.value,addresses.value]=await Promise.all([api('/orders'),api('/addresses')])}catch(e:any){error.value=e.message}}onMounted(load);watch(()=>route.params.tab,load);async function pay(id:string){await api(`/demo/payments/${id}/succeed`,{method:'POST'});load()}async function cancel(id:string){await api(`/orders/${id}/cancel`,{method:'POST'});load()}</script>
<template><main class="container page"><header class="page-title"><small>YOUR ACCOUNT</small><h1>Hello, {{session.user?.name?.split(' ')[0]}}.</h1></header><div class="account"><aside><RouterLink to="/account/orders">Orders</RouterLink><RouterLink to="/account/addresses">Addresses</RouterLink><button @click="session.logout();router.push('/')">Sign out</button></aside><section><p v-if="error" class="notice">{{error}}</p><template v-if="route.params.tab==='addresses'"><h2>Saved addresses</h2><article v-for="a in addresses" class="address"><b>{{a.recipientName}}</b><p>{{a.addressLine}}<br/>{{a.city}}, {{a.province}} {{a.postalCode}}</p></article><RouterLink to="/checkout" class="button">Add address at checkout</RouterLink></template><template v-else><h2>Your orders</h2><div v-if="!orders.length" class="empty">No orders yet. <RouterLink to="/products">Start exploring</RouterLink></div><article v-for="o in orders" class="order"><div><small>{{new Date(o.createdAt).toLocaleDateString('id-ID')}}</small><h3>{{o.orderNumber}}</h3><p>{{o.items.map((i:any)=>`${i.productName} × ${i.quantity}`).join(', ')}}</p></div><div><b>{{idr(o.totalAmount)}}</b><span class="status" :class="o.paymentStatus.toLowerCase()">{{o.paymentStatus}}</span><button v-if="o.paymentStatus==='PENDING'" class="text-button" @click="pay(o.id)">Simulate payment</button><button v-if="o.paymentStatus==='PENDING'" class="text-button" @click="cancel(o.id)">Cancel</button></div></article></template></section></div></main></template>
